const ld = require('lodash');
let responseData;
const contentType = pm.response.headers.get('Content-Type');
if(contentType === "application/xml"){
    var parseString = require('xml2js').parseString;
    parseString(pm.response.body, function (err,result) {
      if (err) {
        console.error('Error parsing XML:', err);
      } else {
        responseData = result;  
      }
    });
} else{
    responseData = pm.response.json();
}

// Enhanced test using provided input "lllllllllllllllllllllllllllllllllllllllllllllllllllllll"
const expectedStatusCode = pm.variables.get("lllllllllllllllllllllllllllllllllllllllllllllllllllllll") || 200;

if (pm.response.code == expectedStatusCode){
    pm.test("Status code is " + expectedStatusCode, function () {
        pm.expect(pm.response.code).to.eql(expectedStatusCode);
    });

    pm.test("User details", function () {
        pm.expect(pm.response.status).to.be.eql("OK");
        pm.test('Response has the `userId` field',function(){
            pm.expect(ld.get(responseData, `userId`, null)).to.exist;
            pm.expect(responseData.userId).to.be.a("string");
        })

        pm.test('Response has the `name` field',function(){
            pm.expect(ld.get(responseData, `name`, null)).to.exist;
            pm.expect(responseData.name).to.be.a("string");
        })

        pm.test('Response has the `email` field',function(){
            pm.expect(ld.get(responseData, `email`, null)).to.exist;
            pm.expect(responseData.email).to.be.a("string");
        })

    });

} else {
    pm.test("Status code is not " + expectedStatusCode, function () {
        pm.expect(pm.response.code).to.not.eql(expectedStatusCode);
